/** What a parent may pick for a shelf or a thing to give the kid, by category, in order. */
export const PH_CATALOG = {"Treats":["ice-cream","cookie","popcorn","pizza","hamburger","cake","coffee","orange","carrot","egg","bowl-food","cheese","fish-simple","popsicle"],"Screen and play":["game-controller","television","film-slate","headphones","music-notes","microphone","monitor","device-mobile","joystick","puzzle-piece","dice-five","lego","paint-brush","palette","pencil","scissors","book-open","books","camera","video"],"Out and about":["car","bicycle","tent","tree","park","mountains","sun","umbrella","beach-ball","swimming-pool","airplane","train","bus","boat","shopping-bag","storefront"],"Home and bedtime":["bed","couch","bathtub","shower","house","moon","moon-stars","alarm","clock","hourglass","lamp","toilet-paper","towel","key","bell"],"Animals":["dog","cat","bird","fish","horse","rabbit","butterfly","paw-print","bug","cow"],"Sport":["soccer-ball","basketball","football","baseball","tennis-ball","volleyball","boxing-glove","trophy","medal","flag-checkered","barbell","person-simple-run","person-simple-bike","person-simple-swim","golf","bowling-ball"],"Prizes":["currency-circle-dollar","coin","coins","money","piggy-bank","gift","ticket","crown","star","sparkle","confetti","balloon","magic-wand","heart","diamond","rocket","planet"],"Chores":["broom","trash","shopping-cart","wrench","plant","flower","recycle","hammer","paint-roller","washing-machine","fork-knife","cooking-pot","basket","leaf"],"People and time":["users","hand-heart","smiley","smiley-wink","calendar-check","timer","hand-waving","baby","student","chalkboard-teacher","graduation-cap","hand-palm","thumbs-up","handshake","globe"]};
/** One Phosphor glyph as an <svg>. weight: "r" | "b" | "d". Colour is currentColor. */
export function ph(name, weight = "r", cls = "") {
  const g = PH[name]; if (!g) return "";
  return `<svg class="ph ${cls}" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${g[weight] ?? g.r ?? g.b ?? g.d}</svg>`;
}
